INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs) VALUES ('p30', 'ru', 'Кашпо «Классик»', 'Кашпо', 'Кашпо, плетённое вручную из искусственного ротанга, со скрытым внутренним вкладышем и дренажом. Лёгкое, не гниёт и не трескается — одинаково хорошо смотрится с живыми растениями дома, на балконе и в саду.', '["Ø30 см","Ø40 см","Ø55 см"]', '{"mat":"Искусственный ротанг","dim":"Со вкладышем и дренажом","fin":"Влагостойкое плетение","wt":"Лёгкое","seat":"Дом, балкон, сад","made":"Ташкент, ручная работа"}');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs) VALUES ('p30', 'uz', '«Klassik» gultuvak', 'Gultuvak', 'Sun’iy rotangdan qo‘lda to‘qilgan gultuvak, yashirin ichki vkladish va drenaj bilan. Yengil, chirimaydi va yorilmaydi — uy, balkon va bog‘da jonli o‘simliklar bilan birdek chiroyli ko‘rinadi.', '["Ø30 sm","Ø40 sm","Ø55 sm"]', '{"mat":"Sun’iy rotang","dim":"Vkladish va drenaj bilan","fin":"Namlikka chidamli to‘quv","wt":"Yengil","seat":"Uy, balkon, bog‘","made":"Toshkent, qo‘l mehnati"}');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs) VALUES ('p30', 'en', 'Classic Planter', 'Planter', 'A planter hand-woven from synthetic rattan, with a hidden inner liner and drainage. Light, rot- and crack-proof — it looks equally good with live plants indoors, on the balcony and in the garden.', '["Ø30 cm","Ø40 cm","Ø55 cm"]', '{"mat":"Synthetic rattan","dim":"With liner & drainage","fin":"Moisture-resistant weave","wt":"Lightweight","seat":"Home, balcony, garden","made":"Tashkent, by hand"}');

