INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs) VALUES ('p32', 'uz', '«Uchlik» gultuvak', 'Gultuvak', 'Sun’iy rotangdan qo‘lda to‘qilgan gultuvak, yashirin ichki vkladish va drenaj bilan. Yengil, chirimaydi va yorilmaydi — uy, balkon va bog‘da jonli o‘simliklar bilan birdek chiroyli ko‘rinadi.', '["Ø30 sm","Ø40 sm","Ø55 sm"]', '{"mat":"Sun’iy rotang","dim":"Vkladish va drenaj bilan","fin":"Namlikka chidamli to‘quv","wt":"Yengil","seat":"Uy, balkon, bog‘","made":"Toshkent, qo‘l mehnati"}');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs) VALUES ('p32', 'en', 'Trio Planter Set', 'Planter', 'A planter hand-woven from synthetic rattan, with a hidden inner liner and drainage. Light, rot- and crack-proof — it looks equally good with live plants indoors, on the balcony and in the garden.', '["Ø30 cm","Ø40 cm","Ø55 cm"]', '{"mat":"Synthetic rattan","dim":"With liner & drainage","fin":"Moisture-resistant weave","wt":"Lightweight","seat":"Home, balcony, garden","made":"Tashkent, by hand"}');

INSERT OR REPLACE INTO products (id, category, look, price_now, price_old, default_size, active, sort) VALUES ('p33', 'basket', 'chest', 165, 0, 1, 1, 32);
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs) VALUES ('p33', 'ru', 'Сундук «Виктория»', 'Корзины и сундуки', 'Сундук и корзина для белья из искусственного ротанга с мягкой тканевой подкладкой и крышкой. Держит форму, не цепляет ткань и проветривается — для хранения белья, пледов, игрушек и мелочей в спальне или ванной.', '["S","M","L"]', '{"mat":"Искусственный ротанг + подкладка","dim":"С крышкой и подкладкой","fin":"Гладкое плетение","wt":"Складная подкладка","seat":"Бельё, пледы, хранение","made":"Ташкент, ручная работа"}');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs) VALUES ('p33', 'uz', '«Viktoriya» sandiq', 'Savat va sandiq', 'Sun’iy rotangdan yumshoq mato astarli va qopqoqli sandiq hamda kir savati. Shaklini saqlaydi, matoga ilashmaydi va shamollatiladi — yotoqxona yoki hammomda kir, pled, o‘yinchoq va mayda buyumlar uchun.', '["S","M","L"]', '{"mat":"Sun’iy rotang + astar","dim":"Qopqoq va astar bilan","fin":"Silliq to‘quv","wt":"Yig‘iladigan astar","seat":"Kir, pled, saqlash","made":"Toshkent, qo‘l mehnati"}');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs) VALUES ('p33', 'en', 'Victoria Chest', 'Baskets & chests', 'A chest and laundry basket in synthetic rattan with a soft fabric liner and lid. Holds its shape, won''t snag fabric and stays ventilated — for laundry, throws, toys and bits in the bedroom or bathroom.', '["S","M","L"]', '{"mat":"Synthetic rattan + liner","dim":"With lid & liner","fin":"Smooth weave","wt":"Foldable liner","seat":"Laundry, throws, storage","made":"Tashkent, by hand"}');

